def shortestSubarray(nums, k):
    from collections import deque
    n = len(nums)
    pre = [0] * (n + 1)
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    best = n + 1
    dq = deque()
    for j in range(n + 1):
        while dq and pre[j] - pre[dq[0]] >= k:
            best = min(best, j - dq.popleft())
        while dq and pre[dq[-1]] >= pre[j]:
            dq.pop()
        dq.append(j)
    return best if best <= n else -1
